package main

import (
	"bytes"
	"crypto/sha256"
	"encoding/binary"
	"encoding/hex"
	"encoding/json"
	"os"
	"path/filepath"
	"strconv"
	"strings"
	"testing"

	"github.com/asdhoaiqqq/darksafe-access/darksafe"
)

// fixtureChain builds: publish v1 with one allow policy (seq 1), an allowed
// decision (seq 2), publish v2 with no policies (seq 3), a default-deny
// decision (seq 4). It archives the full export and returns the file path
// and the separately retained checkpoint.
func fixtureChain(t *testing.T, org string) (string, darksafe.Checkpoint) {
	t.Helper()
	s := darksafe.NewStore()
	s.Publish(org, 0, []darksafe.Policy{
		{ID: "p1 ledger", Subject: "u1", Action: "read", Scope: "org/a", Effect: darksafe.EffectAllow},
	})
	s.Decide(org, darksafe.OrgRequest{
		SubjectOrg: org, ResourceOrg: org,
		Subject:  darksafe.Subject{ID: "u1"},
		Resource: darksafe.Resource{ID: "r1", Scope: "org/a"},
		Action:   "read",
	})
	if v, err := s.Publish(org, 1, nil); err != nil || v != 2 {
		t.Fatalf("publish v2: %d %v", v, err)
	}
	s.Decide(org, darksafe.OrgRequest{
		SubjectOrg: org, ResourceOrg: org,
		Subject:  darksafe.Subject{ID: "u1"},
		Resource: darksafe.Resource{ID: "r1", Scope: "org/a"},
		Action:   "read",
	})
	recs, cp, err := s.AuditExport(org, 0)
	if err != nil {
		t.Fatal(err)
	}
	archive, err := darksafe.EncodeAuditArchive(org, recs, cp)
	if err != nil {
		t.Fatal(err)
	}
	path := filepath.Join(t.TempDir(), "audit.bin")
	if err := os.WriteFile(path, archive, 0o600); err != nil {
		t.Fatal(err)
	}
	return path, cp
}

// runDispatch invokes the full top-level dispatch and captures everything.
func runDispatch(t *testing.T, args ...string) (int, string, string) {
	t.Helper()
	var stdout, stderr bytes.Buffer
	code := dispatch(append([]string{"darksafe"}, args...), &stdout, &stderr)
	return code, stdout.String(), stderr.String()
}

func reviewArgs(path, org string, seq, endSeq int, fp string) []string {
	return []string{
		"review",
		"--archive", path,
		"--org", org,
		"--seq", strconv.Itoa(seq),
		"--end-seq", strconv.Itoa(endSeq),
		"--fingerprint", fp,
	}
}

// TestReviewSuccessPrintsBothDecisions verifies the happy path: both the
// original and recomputed decisions are shown with allowance, reason,
// matched policies and version, plus an explicit consistency verdict.
func TestReviewSuccessPrintsBothDecisions(t *testing.T) {
	const org = "acme payments" // spaces in the organization name
	path, cp := fixtureChain(t, org)

	code, out, errOut := runDispatch(t, reviewArgs(path, org, 2, cp.EndSeq, cp.Fingerprint)...)
	if code != 0 {
		t.Fatalf("exit = %d, stderr = %q", code, errOut)
	}
	if errOut != "" {
		t.Fatalf("unexpected stderr: %q", errOut)
	}
	for _, want := range []string{
		"target sequence: 2",
		"original decision:",
		"recomputed decision:",
		"allowed: true",
		`reason: "matched allow policy"`,
		`matched policies: ["p1 ledger"]`,
		"policy version: 1",
		"consistent: yes",
	} {
		if !strings.Contains(out, want) {
			t.Fatalf("output missing %q:\n%s", want, out)
		}
	}
}

// TestReviewUsesRecordedVersionNotNewer proves a later publish cannot change
// the recomputed decision: seq 2 used v1 even though v2 (no policies) is the
// current version at export time; seq 4 used v2 and denies by default.
func TestReviewUsesRecordedVersionNotNewer(t *testing.T) {
	const org = "acme"
	path, cp := fixtureChain(t, org)

	code, early, _ := runDispatch(t, reviewArgs(path, org, 2, cp.EndSeq, cp.Fingerprint)...)
	if code != 0 {
		t.Fatalf("seq 2 exit = %d", code)
	}
	if !strings.Contains(early, "allowed: true") || !strings.Contains(early, "policy version: 1") {
		t.Fatalf("early decision must replay v1 allow:\n%s", early)
	}

	code, late, _ := runDispatch(t, reviewArgs(path, org, 4, cp.EndSeq, cp.Fingerprint)...)
	if code != 0 {
		t.Fatalf("seq 4 exit = %d", code)
	}
	if !strings.Contains(late, "allowed: false") ||
		!strings.Contains(late, `reason: "no matching allow policy"`) ||
		!strings.Contains(late, "policy version: 2") {
		t.Fatalf("late decision must replay v2 default deny:\n%s", late)
	}
}

// TestReviewInconsistencyRendersCompletely covers the rendering of a
// legitimate-but-inconsistent result: both decisions are printed in full,
// the disagreement is explicit, and it is still a successful exit.
func TestReviewInconsistencyRendersCompletely(t *testing.T) {
	var stdout bytes.Buffer
	printReview(&stdout, darksafe.OfflineDecisionReview{
		Seq: 7,
		Original: darksafe.Decision{
			Allowed: true, Reason: "matched allow policy",
			Matched: []string{"p1"}, Version: 3,
		},
		Recomputed: darksafe.Decision{
			Allowed: false, Reason: "matched deny policy",
			Matched: []string{"p1", "p2"}, Version: 3,
		},
		Consistent: false,
	})
	out := stdout.String()
	for _, want := range []string{
		"target sequence: 7",
		"original decision:",
		"recomputed decision:",
		"consistent: no",
		`reason: "matched allow policy"`,
		`reason: "matched deny policy"`,
		`matched policies: ["p1", "p2"]`,
	} {
		if !strings.Contains(out, want) {
			t.Fatalf("inconsistent output missing %q:\n%s", want, out)
		}
	}
}

// TestReviewUsageFailuresExitTwo covers every exit-2 condition: missing
// required inputs, unparsable integers, non-positive target, negative end
// sequence, unknown/unexpected arguments, and an unreadable archive.
func TestReviewUsageFailuresExitTwo(t *testing.T) {
	const org = "acme"
	path, cp := fixtureChain(t, org)
	base := reviewArgs(path, org, 2, cp.EndSeq, cp.Fingerprint)

	dropFlag := func(name string) []string {
		out := make([]string, 0, len(base)-2)
		for i := 0; i < len(base); i++ {
			if base[i] == name {
				i++ // also drop its value
				continue
			}
			out = append(out, base[i])
		}
		return out
	}

	// --flag=value with a non-integer value must fail exactly like the
	// separated form.
	eqBad := reviewArgs(path, org, 2, cp.EndSeq, cp.Fingerprint)
	for i := range eqBad {
		if eqBad[i] == "--seq" {
			eqBad[i] = "--seq=nope"
			eqBad = append(eqBad[:i+1], eqBad[i+2:]...)
			break
		}
	}

	cases := []struct {
		name string
		args []string
	}{
		{"no arguments", []string{"review"}},
		{"missing archive", dropFlag("--archive")},
		{"missing org", dropFlag("--org")},
		{"missing seq", dropFlag("--seq")},
		{"missing end-seq", dropFlag("--end-seq")},
		{"missing fingerprint", dropFlag("--fingerprint")},
		{"non-integer seq", replaceArg(base, "--seq", "abc")},
		{"float seq", replaceArg(base, "--seq", "1.5")},
		{"non-integer end-seq", replaceArg(base, "--end-seq", "xx")},
		{"zero seq", replaceArg(base, "--seq", "0")},
		{"negative seq", replaceArg(base, "--seq", "-4")},
		{"negative end-seq", replaceArg(base, "--end-seq", "-1")},
		{"equals form bad int", eqBad},
		{"unknown flag", append(append([]string{}, base...), "--bogus")},
		{"positional argument", append(append([]string{}, base...), "leftover")},
		{"missing file", replaceArg(base, "--archive", filepath.Join(t.TempDir(), "nope.bin"))},
		{"archive is directory", replaceArg(base, "--archive", t.TempDir())},
	}

	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			code, out, errOut := runDispatch(t, tc.args...)
			if code != 2 {
				t.Fatalf("exit = %d, want 2; stdout=%q stderr=%q", code, out, errOut)
			}
			if errOut == "" {
				t.Fatal("expected a specific reason on stderr")
			}
			if out != "" {
				t.Fatalf("usage failure must print nothing to stdout, got %q", out)
			}
		})
	}
}

func replaceArg(base []string, flag, value string) []string {
	out := append([]string{}, base...)
	for i := range out {
		if out[i] == flag {
			out[i+1] = value
			return out
		}
	}
	return out
}

// TestReviewMaterialAndTargetFailuresExitOne covers the exit-1 family:
// unrecognized bytes, checkpoint mismatch (the archive's own checkpoint
// cannot substitute), a target past the export, and a non-decision target.
// None of them may print partial decision content.
func TestReviewMaterialAndTargetFailuresExitOne(t *testing.T) {
	const org = "acme"
	path, cp := fixtureChain(t, org)
	dir := filepath.Dir(path)

	garbage := filepath.Join(dir, "garbage.bin")
	if err := os.WriteFile(garbage, []byte("not an archive"), 0o600); err != nil {
		t.Fatal(err)
	}

	// Flip a byte in a valid file: checksum/framing fails and no records are
	// delivered.
	good, err := os.ReadFile(path)
	if err != nil {
		t.Fatal(err)
	}
	corrupt := append([]byte(nil), good...)
	corrupt[len(corrupt)-40] ^= 0x01
	corruptPath := filepath.Join(dir, "corrupt.bin")
	if err := os.WriteFile(corruptPath, corrupt, 0o600); err != nil {
		t.Fatal(err)
	}

	cases := []struct {
		name string
		args []string
	}{
		{"unrecognized archive", reviewArgs(garbage, org, 2, cp.EndSeq, cp.Fingerprint)},
		{"corrupted bytes", reviewArgs(corruptPath, org, 2, cp.EndSeq, cp.Fingerprint)},
		{"wrong fingerprint", reviewArgs(path, org, 2, cp.EndSeq, cp.Fingerprint[:len(cp.Fingerprint)-1]+"0")},
		{"foreign organization", reviewArgs(path, "globex", 2, cp.EndSeq, cp.Fingerprint)},
		{"wrong end sequence", reviewArgs(path, org, 2, cp.EndSeq-1, cp.Fingerprint)},
		{"target past export", reviewArgs(path, org, 99, cp.EndSeq, cp.Fingerprint)},
		{"target is policy change", reviewArgs(path, org, 1, cp.EndSeq, cp.Fingerprint)},
	}

	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			code, out, errOut := runDispatch(t, tc.args...)
			if code != 1 {
				t.Fatalf("exit = %d, want 1; stderr=%q", code, errOut)
			}
			if errOut == "" {
				t.Fatal("expected a distinguishable failure reason on stderr")
			}
			if out != "" {
				t.Fatalf("failure must not print a partial decision, stdout=%q", out)
			}
		})
	}
}

// archiveMagicV1 mirrors the darksafe package's stable framing prefix; the
// format is explicitly versioned (…-v1), so the CLI test relies only on its
// published layout.
const archiveMagicV1 = "darksafe-audit-archive-v1\n"

// reframeArchive parses one archive frame, lets mutate alter the payload in
// place, and rebuilds a frame with a consistent declared length and
// checksum, so a test can tamper content without tripping framing/checksum
// checks and reach the library's whole-chain validation.
func reframeArchive(t *testing.T, data []byte, mutate func(payload []byte)) []byte {
	t.Helper()
	magicLen := len(archiveMagicV1)
	n := int(binary.BigEndian.Uint32(data[magicLen : magicLen+4]))
	payload := append([]byte(nil), data[magicLen+4:magicLen+4+n]...)
	mutate(payload)
	out := append([]byte(nil), archiveMagicV1...)
	var lb [4]byte
	binary.BigEndian.PutUint32(lb[:], uint32(len(payload)))
	out = append(out, lb[:]...)
	out = append(out, payload...)
	sum := sha256.Sum256(payload)
	return append(out, sum[:]...)
}

// TestReviewValidatesMaterialAfterTarget builds a chain whose early decision
// (seq 2) is the review target but whose LATER record (seq 4, a uniquely
// named subject) is tampered with a valid checksum. Decode parses it and the
// whole-chain check must reject it: even an early target validates every
// record, and no partial decision is printed.
func TestReviewValidatesMaterialAfterTarget(t *testing.T) {
	const org = "acme"
	s := darksafe.NewStore()
	s.Publish(org, 0, []darksafe.Policy{
		{ID: "p1", Subject: "u1", Action: "read", Scope: "org/a", Effect: darksafe.EffectAllow},
	})
	s.Decide(org, darksafe.OrgRequest{
		SubjectOrg: org, ResourceOrg: org,
		Subject:  darksafe.Subject{ID: "u1"},
		Resource: darksafe.Resource{ID: "r1", Scope: "org/a"},
		Action:   "read",
	})
	s.Publish(org, 1, nil)
	// The later decision uses a unique subject so its bytes are locatable and
	// cannot be confused with the early record under review.
	s.Decide(org, darksafe.OrgRequest{
		SubjectOrg: org, ResourceOrg: org,
		Subject:  darksafe.Subject{ID: "late-subject"},
		Resource: darksafe.Resource{ID: "r9", Scope: "org/a"},
		Action:   "read",
	})
	recs, cp, err := s.AuditExport(org, 0)
	if err != nil {
		t.Fatal(err)
	}
	good, err := darksafe.EncodeAuditArchive(org, recs, cp)
	if err != nil {
		t.Fatal(err)
	}

	tampered := reframeArchive(t, good, func(payload []byte) {
		idx := bytes.Index(payload, []byte("late-subject"))
		if idx < 0 {
			t.Fatal("later record subject not located in payload")
		}
		payload[idx] ^= 0x01 // same length; only the later record's content changes
	})
	path := filepath.Join(t.TempDir(), "late-damage.bin")
	if err := os.WriteFile(path, tampered, 0o600); err != nil {
		t.Fatal(err)
	}

	code, out, errOut := runDispatch(t, reviewArgs(path, org, 2, cp.EndSeq, cp.Fingerprint)...)
	if code != 1 {
		t.Fatalf("later-record tamper exit = %d, want 1; %s", code, errOut)
	}
	if !strings.Contains(errOut, "invalid audit range") {
		t.Fatalf("tampering a later record must fail chain validation, got %q", errOut)
	}
	if out != "" {
		t.Fatalf("no partial output allowed, got %q", out)
	}
}

// TestReviewPreservesDistinctRawBytes ensures output quoting keeps a lone
// 0xFF, a lone 0xFE and a genuine U+FFFD in matched policy identifiers
// distinguishable rather than folding all invalid bytes onto one rune.
func TestReviewPreservesDistinctRawBytes(t *testing.T) {
	rawIDArchive := func(t *testing.T, id string) (string, darksafe.Checkpoint) {
		t.Helper()
		const org = "raw org"
		s := darksafe.NewStore()
		s.Publish(org, 0, []darksafe.Policy{
			{ID: id, Subject: "u1", Action: "read", Scope: "org/a", Effect: darksafe.EffectAllow},
		})
		s.Decide(org, darksafe.OrgRequest{
			SubjectOrg: org, ResourceOrg: org,
			Subject:  darksafe.Subject{ID: "u1"},
			Resource: darksafe.Resource{ID: "r", Scope: "org/a"},
			Action:   "read",
		})
		recs, cp, err := s.AuditExport(org, 0)
		if err != nil {
			t.Fatal(err)
		}
		arc, err := darksafe.EncodeAuditArchive(org, recs, cp)
		if err != nil {
			t.Fatal(err)
		}
		p := filepath.Join(t.TempDir(), "raw.bin")
		if err := os.WriteFile(p, arc, 0o600); err != nil {
			t.Fatal(err)
		}
		return p, cp
	}

	outputs := map[string]string{}
	for name, id := range map[string]string{
		"ff":   "p\xff",
		"fe":   "p\xfe",
		"uffd": "p�",
	} {
		path, cp := rawIDArchive(t, id)
		code, out, errOut := runDispatch(t, reviewArgs(path, "raw org", 2, cp.EndSeq, cp.Fingerprint)...)
		if code != 0 {
			t.Fatalf("%s review failed: %s", name, errOut)
		}
		outputs[name] = out
	}
	if outputs["ff"] == outputs["fe"] || outputs["ff"] == outputs["uffd"] || outputs["fe"] == outputs["uffd"] {
		t.Fatalf("distinct raw bytes collapsed:\nff:  %q\nfe:  %q\nuffd:%q",
			outputs["ff"], outputs["fe"], outputs["uffd"])
	}
	if !strings.Contains(outputs["ff"], `"p\xff"`) {
		t.Fatalf("0xFF must render as quoted \\xff:\n%s", outputs["ff"])
	}
	if !strings.Contains(outputs["fe"], `"p\xfe"`) {
		t.Fatalf("0xFE must render as quoted \\xfe:\n%s", outputs["fe"])
	}
	if !strings.Contains(outputs["uffd"], `p�`) {
		t.Fatalf("a real U+FFFD must render as itself, not an escape:\n%s", outputs["uffd"])
	}
}

// syntheticEnvelope mirrors the library's internal fingerprint envelope for
// the all-valid-UTF-8 case: record fingerprints are the SHA-256 of this JSON
// shape (see audit.go's hashEnvelope), and the genesis root is
// SHA-256("darksafe-audit-genesis\x00"+org). Field order and tags are
// load-bearing because the hash is order-sensitive; EncodeAuditArchive below
// independently re-verifies every fingerprint, so any drift fails the test
// loudly rather than silently testing the wrong thing.
type syntheticEnvelope struct {
	Org             string                   `json:"org"`
	Seq             int                      `json:"seq"`
	Kind            string                   `json:"kind"`
	Change          *darksafe.PolicyChange   `json:"change,omitempty"`
	Decision        *darksafe.DecisionRecord `json:"decision,omitempty"`
	PrevFingerprint string                   `json:"prev"`
}

func genesisFingerprintHex(org string) string {
	sum := sha256.Sum256([]byte("darksafe-audit-genesis\x00" + org))
	return hex.EncodeToString(sum[:])
}

func envelopeFingerprint(env syntheticEnvelope) string {
	b, err := json.Marshal(env)
	if err != nil {
		panic(err)
	}
	sum := sha256.Sum256(b)
	return hex.EncodeToString(sum[:])
}

// TestReviewInconsistentButValidExitsZero proves the central exit-code rule:
// material that chains correctly but whose recorded decision contradicts the
// recorded policy is NOT archive damage. The command prints both decisions in
// full, marks the disagreement, and still exits 0.
func TestReviewInconsistentButValidExitsZero(t *testing.T) {
	const org = "acme"
	req := darksafe.OrgRequest{
		SubjectOrg: org, ResourceOrg: org,
		Subject:  darksafe.Subject{ID: "u1"},
		Resource: darksafe.Resource{ID: "r1", Scope: "org/a"},
		Action:   "read",
	}
	rec1 := darksafe.AuditRecord{
		Org: org, Seq: 1, Kind: darksafe.AuditPolicyChange,
		Change: &darksafe.PolicyChange{
			Version: 1,
			Policies: []darksafe.Policy{
				{ID: "p1", Subject: "u1", Action: "read", Scope: "org/a", Effect: darksafe.EffectAllow},
			},
		},
		PrevFingerprint: genesisFingerprintHex(org),
	}
	rec1.Fingerprint = envelopeFingerprint(syntheticEnvelope{
		Org: rec1.Org, Seq: rec1.Seq, Kind: rec1.Kind,
		Change: rec1.Change, PrevFingerprint: rec1.PrevFingerprint,
	})
	// The recorded decision claims a deny the v1 policy cannot produce.
	rec2 := darksafe.AuditRecord{
		Org: org, Seq: 2, Kind: darksafe.AuditDecision,
		Decision: &darksafe.DecisionRecord{
			Request: req,
			Decision: darksafe.Decision{
				Allowed: false, Reason: "matched deny policy", Matched: []string{"p1"}, Version: 1,
			},
		},
		PrevFingerprint: rec1.Fingerprint,
	}
	rec2.Fingerprint = envelopeFingerprint(syntheticEnvelope{
		Org: rec2.Org, Seq: rec2.Seq, Kind: rec2.Kind,
		Decision: rec2.Decision, PrevFingerprint: rec2.PrevFingerprint,
	})
	records := []darksafe.AuditRecord{rec1, rec2}
	cp := darksafe.Checkpoint{Org: org, EndSeq: 2, Fingerprint: rec2.Fingerprint}

	arc, err := darksafe.EncodeAuditArchive(org, records, cp)
	if err != nil {
		t.Fatalf("synthetic chain must encode/verify: %v", err)
	}
	path := filepath.Join(t.TempDir(), "inconsistent.bin")
	if err := os.WriteFile(path, arc, 0o600); err != nil {
		t.Fatal(err)
	}

	code, out, errOut := runDispatch(t, reviewArgs(path, org, 2, cp.EndSeq, cp.Fingerprint)...)
	if code != 0 {
		t.Fatalf("a legitimate-but-inconsistent review must exit 0, got %d: %s", code, errOut)
	}
	for _, want := range []string{
		"target sequence: 2",
		"original decision:",
		"recomputed decision:",
		"consistent: no",
		// Original preserved verbatim.
		`reason: "matched deny policy"`,
		// Recomputed from the recorded request against v1: allow.
		`reason: "matched allow policy"`,
		"allowed: false",
		"allowed: true",
	} {
		if !strings.Contains(out, want) {
			t.Fatalf("inconsistent review output missing %q:\n%s", want, out)
		}
	}
}

// TestReviewMissingHistoricalVersionExitsOne builds a chain that is
// internally consistent but whose decision names version 5 although no
// policy change record in the material ever published it. Decode succeeds,
// targeting succeeds, but the historical version cannot be obtained: a
// distinguishable failure, exit 1, never a silent substitution with a newer
// version.
func TestReviewMissingHistoricalVersionExitsOne(t *testing.T) {
	const org = "acme"
	rec := darksafe.AuditRecord{
		Org: org, Seq: 1, Kind: darksafe.AuditDecision,
		Decision: &darksafe.DecisionRecord{
			Request: darksafe.OrgRequest{
				SubjectOrg: org, ResourceOrg: org,
				Subject:  darksafe.Subject{ID: "u1"},
				Resource: darksafe.Resource{ID: "r1", Scope: "org/a"},
				Action:   "read",
			},
			Decision: darksafe.Decision{
				Allowed: false, Reason: "no matching allow policy", Matched: nil, Version: 5,
			},
		},
		PrevFingerprint: genesisFingerprintHex(org),
	}
	rec.Fingerprint = envelopeFingerprint(syntheticEnvelope{
		Org: rec.Org, Seq: rec.Seq, Kind: rec.Kind,
		Decision: rec.Decision, PrevFingerprint: rec.PrevFingerprint,
	})
	records := []darksafe.AuditRecord{rec}
	cp := darksafe.Checkpoint{Org: org, EndSeq: 1, Fingerprint: rec.Fingerprint}
	arc, err := darksafe.EncodeAuditArchive(org, records, cp)
	if err != nil {
		t.Fatalf("chain must encode: %v", err)
	}
	path := filepath.Join(t.TempDir(), "missing-version.bin")
	if err := os.WriteFile(path, arc, 0o600); err != nil {
		t.Fatal(err)
	}

	code, out, errOut := runDispatch(t, reviewArgs(path, org, 1, cp.EndSeq, cp.Fingerprint)...)
	if code != 1 {
		t.Fatalf("unavailable historical version must exit 1, got %d: %s", code, errOut)
	}
	if !strings.Contains(errOut, "version not found") {
		t.Fatalf("failure must name the missing version distinctly, got %q", errOut)
	}
	if out != "" {
		t.Fatalf("failure must print no partial decision, got %q", out)
	}
}

func TestReviewHelp(t *testing.T) {
	for _, flag := range []string{"--help", "-h"} {
		code, out, errOut := runDispatch(t, "review", flag)
		if code != 0 || errOut != "" {
			t.Fatalf("review %s: code=%d stderr=%q", flag, code, errOut)
		}
		for _, want := range []string{
			"--archive", "--org", "--seq", "--end-seq", "--fingerprint",
			"informational only", "Example:", "darksafe review",
			"Exit codes",
		} {
			if !strings.Contains(out, want) {
				t.Fatalf("review help missing %q:\n%s", want, out)
			}
		}
	}
}

// TestLegencyCommandsSurvive locks in the original CLI surface.
func TestLegacyCommandsSurvive(t *testing.T) {
	if code, out, _ := runDispatch(t); code != 0 || !strings.Contains(out, "summary:") {
		t.Fatalf("no-arg demo changed: code=%d out=%q", code, out)
	}
	if code, out, _ := runDispatch(t, "demo"); code != 0 || !strings.Contains(out, "summary:") {
		t.Fatalf("demo changed: code=%d out=%q", code, out)
	}
	if code, out, _ := runDispatch(t, "version"); code != 0 || strings.TrimSpace(out) != "darksafe 0.1.0" {
		t.Fatalf("version changed: code=%d out=%q", code, out)
	}
	if code, out, _ := runDispatch(t, "help"); code != 0 || !strings.Contains(out, "usage:") {
		t.Fatalf("help changed: code=%d out=%q", code, out)
	}
	if code, _, errOut := runDispatch(t, "bogus"); code != 2 || errOut == "" {
		t.Fatalf("unknown command exit = %d stderr=%q", code, errOut)
	}
}

// TestReviewIsReadOnlyOnFile ensures a successful review leaves the archive
// bytes untouched.
func TestReviewIsReadOnlyOnFile(t *testing.T) {
	const org = "acme"
	path, cp := fixtureChain(t, org)
	before, err := os.ReadFile(path)
	if err != nil {
		t.Fatal(err)
	}
	if code, _, errOut := runDispatch(t, reviewArgs(path, org, 2, cp.EndSeq, cp.Fingerprint)...); code != 0 {
		t.Fatalf("review: %d %s", code, errOut)
	}
	after, err := os.ReadFile(path)
	if err != nil {
		t.Fatal(err)
	}
	if !bytes.Equal(before, after) {
		t.Fatal("review modified the archive file")
	}
}

// This file implements lossless archiving of one organization's audit
// export. AuditExport hands back detached in-memory records and the caller
// separately retains the checkpoint pinning them; an archive serializes the
// export so it can be saved to a file when the service instance ends and
// read back later, still paired with the caller's own checkpoint and still
// usable as the material for RecheckDecisionOffline.
//
// The format is a length-delimited binary encoding built by hand rather
// than encoding/json: JSON text cannot carry bytes that are not valid
// UTF-8 without silently replacing them with U+FFFD, which would collapse
// genuinely different content (a lone 0xFF, a lone 0xFE and a real U+FFFD)
// onto identical records and change their fingerprints. Every string is
// written from its exact bytes with a length prefix, and nil slices,
// non-nil empty slices and absent payloads are each marked explicitly.
//
// Integrity never comes from trust in the file. A decode reconstructs the
// records and then runs the same whole-material VerifyAudit chain check
// against the checkpoint the caller supplies independently; the checkpoint
// embedded in the archive is informational only and never authoritative.
package darksafe

import (
	"bytes"
	"crypto/sha256"
	"encoding/binary"
	"errors"
	"fmt"
)

// ErrInvalidArchive means archive bytes are not a recognizable, complete,
// untampered audit archive: a foreign/truncated/trailing-byte framing, a
// failed checksum, or content that does not decode. Content-level failures
// (missing or mismatched organization, missing, out-of-order or modified
// records, a mismatched checkpoint) keep using ErrMissingOrganization and
// ErrInvalidRange exactly as the other audit entry points do.
var ErrInvalidArchive = errors.New("darksafe: invalid audit archive")

// Archive framing:
//
//	magic   = archiveMagic
//	u32 BE  = byte length of the payload that follows
//	payload = archivePayloadLen bytes
//	32 bytes = SHA-256 checksum of payload
//
// A second archive concatenated to a first is trailing material, not a
// second frame: a read consumes exactly one frame and rejects any byte
// beyond it.
const archiveMagic = "darksafe-audit-archive-v1\n"

const (
	archiveTagBoolFalse byte = 0
	archiveTagBoolTrue  byte = 1
	archiveTagNil       byte = 0
	archiveTagPresent   byte = 1
)

// archiveWriter appends length-delimited fields to a byte buffer.
type archiveWriter struct {
	buf []byte
	err error
}

func (w *archiveWriter) raw(data []byte) {
	w.buf = append(w.buf, data...)
}

// u32 writes a non-negative int as a big-endian uint32.
func (w *archiveWriter) u32(v int) {
	if v < 0 || uint64(v) > 0xffffffff {
		w.err = fmt.Errorf("%w: length out of range: %d", ErrInvalidArchive, v)
		return
	}
	var b [4]byte
	binary.BigEndian.PutUint32(b[:], uint32(v))
	w.buf = append(w.buf, b[:]...)
}

func (w *archiveWriter) boolean(v bool) {
	if v {
		w.buf = append(w.buf, archiveTagBoolTrue)
	} else {
		w.buf = append(w.buf, archiveTagBoolFalse)
	}
}

// put appends one raw framing byte. It is the archive sink's side of the
// shared list shape: the list presence marker (archiveTagNil for nil,
// archiveTagPresent for a non-nil list) goes into the payload verbatim.
func (w *archiveWriter) put(b byte) {
	w.buf = append(w.buf, b)
}

// listCount writes a list element count through the archive's own
// range-checked u32, so a list length the uint32 format cannot represent
// still fails the whole archive with the existing ErrInvalidArchive rather
// than emitting truncated framing or returning partial bytes.
func (w *archiveWriter) listCount(n int) {
	w.u32(n)
}

// stringField writes a string from its exact memory bytes. Nothing is
// validated, replaced or normalized: a lone 0xFF reaches the output as
// itself and stays distinguishable from 0xFE and a genuine U+FFFD.
func (w *archiveWriter) stringField(s string) {
	w.u32(len(s))
	if w.err != nil {
		return
	}
	w.buf = append(w.buf, s...)
}

// policy writes one Policy by walking the single policy field table, so the
// archive's field order is the fingerprint's order by construction. Even the
// fingerprint-optional ResourceID is always written here (empty included),
// so every field round trips on its own; its placement is fixed by the
// table and therefore cannot move a fingerprint boundary.
func (w *archiveWriter) policy(p Policy) {
	for i := range policyFields {
		f := &policyFields[i]
		switch f.kind {
		case policyFieldString, policyFieldOptionalString:
			w.stringField(f.getString(p))
		case policyFieldBool:
			w.boolean(f.getBool(p))
		}
	}
}

// change writes the policy-change payload, or a single absence marker:
// VerifyAudit only ever accepts a change payload on a policy-change record
// and its absence otherwise, but the distinction is encoded explicitly so
// decode never has to reconstruct a shape. A present payload walks the
// single policy-change field table, so the archive's field order is the
// fingerprint's order by construction and every change field round trips.
func (w *archiveWriter) change(c *PolicyChange) {
	if c == nil {
		w.buf = append(w.buf, archiveTagNil)
		return
	}
	w.buf = append(w.buf, archiveTagPresent)
	for i := range changeFields {
		f := &changeFields[i]
		switch f.kind {
		case changeFieldInt:
			w.u32(f.getInt(c))
		case changeFieldPolicyList:
			writeListShape(w, f.getPolicies(c), w.policy)
		case changeFieldBool:
			w.boolean(f.getBool(c))
		}
	}
}

// decisionRecord writes the decision payload, or a single absence marker:
// VerifyAudit only ever accepts a decision payload on a decision record and
// its absence otherwise, but the distinction is encoded explicitly so decode
// never has to reconstruct a shape. A present payload walks the single
// decision field table, so the archive's field order is the fingerprint's
// order by construction and every request and decision field round trips.
func (w *archiveWriter) decisionRecord(d *DecisionRecord) {
	if d == nil {
		w.buf = append(w.buf, archiveTagNil)
		return
	}
	w.buf = append(w.buf, archiveTagPresent)
	for i := range decisionFields {
		f := &decisionFields[i]
		switch f.kind {
		case decisionFieldString:
			w.stringField(f.getString(d))
		case decisionFieldStringList:
			writeListShape(w, f.getList(d), w.stringField)
		case decisionFieldBool:
			w.boolean(f.getBool(d))
		case decisionFieldInt:
			w.u32(f.getInt(d))
		}
	}
}

// EncodeAuditArchive serializes one complete audit export into savable
// bytes. org is the organization name, records is its complete chain from
// sequence 1 (a valid prefix ending at some historical sequence is enough,
// provided cp pins exactly that sequence), and cp is the checkpoint the
// caller separately retains. An organization with no records archives too:
// records is empty and cp is its sequence-0 genesis checkpoint.
//
// The whole material is validated exactly as VerifyAudit would before any
// bytes are returned: a missing organization is ErrMissingOrganization, and
// a missing, out-of-order or foreign record, modified content or checkpoint
// mismatch is ErrInvalidRange. On failure no archive bytes are returned.
// The checkpoint is carried in the archive for reference, but never stands
// in for the separately retained evidence: DecodeAuditArchive always
// validates against the checkpoint handed to it. The call is read-only:
// neither the records nor any service state are mutated and no audit record
// is appended.
func EncodeAuditArchive(org string, records []AuditRecord, cp Checkpoint) ([]byte, error) {
	if org == "" {
		return nil, ErrMissingOrganization
	}
	if err := VerifyAudit(org, records, cp); err != nil {
		return nil, err
	}

	pw := &archiveWriter{}
	pw.stringField(org)
	pw.u32(cp.EndSeq)
	pw.stringField(cp.Fingerprint)
	pw.u32(len(records))
	for i := range records {
		rec := &records[i]
		// The outer record fields walk the single record field table, so
		// the archive's record layout is the fingerprint envelope's layout
		// — plus the record's own fingerprint, which the envelope excludes
		// — by construction, and no outer field can be skipped or
		// reordered here alone.
		for j := range recordFields {
			f := &recordFields[j]
			switch f.kind {
			case recordFieldString:
				pw.stringField(f.getString(rec))
			case recordFieldInt:
				pw.u32(f.getInt(rec))
			case recordFieldChange:
				pw.change(f.getChange(rec))
			case recordFieldDecision:
				pw.decisionRecord(f.getDecision(rec))
			}
		}
	}
	if pw.err != nil {
		return nil, pw.err
	}
	payload := pw.buf

	out := make([]byte, 0, len(archiveMagic)+4+len(payload)+sha256.Size)
	out = append(out, archiveMagic...)
	var lenBuf [4]byte
	binary.BigEndian.PutUint32(lenBuf[:], uint32(len(payload)))
	out = append(out, lenBuf[:]...)
	out = append(out, payload...)
	sum := sha256.Sum256(payload)
	out = append(out, sum[:]...)
	return out, nil
}

// archiveReader walks one payload without copying string contents: string
// fields are backed by the payload slice itself, which is owned by the
// decoder and never returned, so callers cannot mutate the input through
// the result.
type archiveReader struct {
	data []byte
	pos  int
	err  error
}

func (r *archiveReader) need(n int) bool {
	if r.err != nil {
		return false
	}
	if n < 0 || r.pos > len(r.data)-n {
		r.err = fmt.Errorf("%w: truncated archive payload", ErrInvalidArchive)
		return false
	}
	return true
}

func (r *archiveReader) marker() byte {
	if !r.need(1) {
		return 0
	}
	b := r.data[r.pos]
	r.pos++
	return b
}

func (r *archiveReader) u32() int {
	if !r.need(4) {
		return 0
	}
	v := int(binary.BigEndian.Uint32(r.data[r.pos : r.pos+4]))
	r.pos += 4
	return v
}

// boundedCount reads a count and proves at least minBytesPerItem bytes
// remain per item, so a hostile payload cannot drive a huge allocation
// with a count its body could never satisfy.
func (r *archiveReader) boundedCount(minBytesPerItem int) int {
	n := r.u32()
	if r.err != nil {
		return 0
	}
	if n < 0 || uint64(n)*uint64(minBytesPerItem) > uint64(len(r.data)-r.pos) {
		r.err = fmt.Errorf("%w: implausible list count %d", ErrInvalidArchive, n)
		return 0
	}
	return n
}

func (r *archiveReader) boolean() bool {
	switch r.marker() {
	case archiveTagBoolTrue:
		return true
	case archiveTagBoolFalse:
		return false
	default:
		if r.err == nil {
			r.err = fmt.Errorf("%w: invalid boolean marker", ErrInvalidArchive)
		}
		return false
	}
}

func (r *archiveReader) stringField() string {
	n := r.u32()
	if r.err != nil {
		return ""
	}
	if !r.need(n) {
		return ""
	}
	// Conversion copies the bytes, so the result never aliases the input.
	s := string(r.data[r.pos : r.pos+n])
	r.pos += n
	return s
}

// readList reads one length-counted list framed by writeListShape on the
// archive sink, whatever its item type: both string lists and the policy
// list decode here. Every list
// kind gets the exact same framing checks — the nil/presence marker, the
// per-item byte floor before any allocation, and each item's own
// truncation/structure errors — so a hostile count can neither drive a
// disproportionate allocation nor deliver a partial list: once an item
// fails, the reader's sticky error fails the whole read.
// minBytesPerItem is the minimum an item could occupy (each string item
// carries one length word; a policy item carries six length words and a
// bool), and is used only to reject counts the remaining bytes could never
// satisfy.
func readList[T any](r *archiveReader, minBytesPerItem int, readItem func() T) []T {
	switch r.marker() {
	case archiveTagNil:
		return nil
	case archiveTagPresent:
	default:
		if r.err == nil {
			r.err = fmt.Errorf("%w: invalid list marker", ErrInvalidArchive)
		}
		return nil
	}
	n := r.boundedCount(minBytesPerItem)
	if r.err != nil {
		return nil
	}
	items := make([]T, n)
	for i := range items {
		items[i] = readItem()
	}
	return items
}

func (r *archiveReader) policy() Policy {
	// Read fields in the single table's (write and fingerprint) order. The
	// fingerprint-optional ResourceID is still a mandatory, fixed field on
	// the archive, so it is read for every policy including the empty one.
	var p Policy
	for i := range policyFields {
		f := &policyFields[i]
		switch f.kind {
		case policyFieldString, policyFieldOptionalString:
			f.setString(&p, r.stringField())
		case policyFieldBool:
			f.setBool(&p, r.boolean())
		}
	}
	return p
}

func (r *archiveReader) change() *PolicyChange {
	switch r.marker() {
	case archiveTagNil:
		return nil
	case archiveTagPresent:
	default:
		if r.err == nil {
			r.err = fmt.Errorf("%w: invalid change payload marker", ErrInvalidArchive)
		}
		return nil
	}
	// Read fields in the single table's (write and fingerprint) order, so a
	// field can never be restored into the wrong member or skipped.
	c := &PolicyChange{}
	for i := range changeFields {
		f := &changeFields[i]
		switch f.kind {
		case changeFieldInt:
			f.setInt(c, r.u32())
		case changeFieldPolicyList:
			// A policy writes six length words (five strings plus
			// ResourceID) and one bool byte at minimum.
			f.setPolicies(c, readList(r, 6*4+1, r.policy))
		case changeFieldBool:
			f.setBool(c, r.boolean())
		}
	}
	return c
}

func (r *archiveReader) decisionRecord() *DecisionRecord {
	switch r.marker() {
	case archiveTagNil:
		return nil
	case archiveTagPresent:
	default:
		if r.err == nil {
			r.err = fmt.Errorf("%w: invalid decision payload marker", ErrInvalidArchive)
		}
		return nil
	}
	// Read fields in the single table's (write and fingerprint) order, so a
	// field can never be restored into the wrong member or skipped.
	d := &DecisionRecord{}
	for i := range decisionFields {
		f := &decisionFields[i]
		switch f.kind {
		case decisionFieldString:
			f.setString(d, r.stringField())
		case decisionFieldStringList:
			// Each string item carries at least one length word.
			f.setList(d, readList(r, 4, r.stringField))
		case decisionFieldBool:
			f.setBool(d, r.boolean())
		case decisionFieldInt:
			f.setInt(d, r.u32())
		}
	}
	return d
}

// decodedArchiveFrame is one archive parsed up to, but not including, the
// content checks: the reconstructed records and the informational
// checkpoint embedded in the header. Nothing at this stage has been
// validated against the caller's organization or retained checkpoint.
type decodedArchiveFrame struct {
	records     []AuditRecord
	org         string
	endSeq      int
	fingerprint string
}

// decodeAuditArchiveFrame parses one frame's framing, checksum and payload.
// It performs no content validation: the embedded organization and
// checkpoint are returned for the caller to compare, and the records are
// not chain-checked until a content-validating entry point runs the single
// VerifyAudit pass.
func decodeAuditArchiveFrame(archive []byte) (decodedArchiveFrame, error) {
	magicLen := len(archiveMagic)
	if len(archive) < magicLen+4+sha256.Size || string(archive[:magicLen]) != archiveMagic {
		return decodedArchiveFrame{}, fmt.Errorf("%w: unrecognized audit archive", ErrInvalidArchive)
	}
	pos := magicLen
	payloadLen := int(binary.BigEndian.Uint32(archive[pos : pos+4]))
	pos += 4
	checksumEnd := pos + payloadLen
	if payloadLen < 0 || checksumEnd+sha256.Size != len(archive) {
		// A short frame is truncation; bytes beyond the one frame (a
		// concatenated second archive, junk appended to a good file) are a
		// framing failure too.
		return decodedArchiveFrame{}, fmt.Errorf("%w: truncated or trailing audit archive bytes", ErrInvalidArchive)
	}
	payload := archive[pos:checksumEnd]
	sum := sha256.Sum256(payload)
	if !bytes.Equal(sum[:], archive[checksumEnd:checksumEnd+sha256.Size]) {
		return decodedArchiveFrame{}, fmt.Errorf("%w: checksum mismatch", ErrInvalidArchive)
	}

	r := &archiveReader{data: payload}
	embeddedOrg := r.stringField()
	embeddedEndSeq := r.u32()
	embeddedFingerprint := r.stringField()
	// Every record writes two payload markers, a sequence word, two
	// fingerprint length words and org/kind length words: 22 bytes even
	// when every string is empty.
	n := r.boundedCount(22)
	if r.err != nil {
		return decodedArchiveFrame{}, r.err
	}
	records := make([]AuditRecord, 0, n)
	for i := 0; i < n; i++ {
		// Read the outer fields in the single record field table's (write
		// and fingerprint) order, so a field can never be restored into the
		// wrong member or skipped.
		var rec AuditRecord
		for j := range recordFields {
			f := &recordFields[j]
			switch f.kind {
			case recordFieldString:
				f.setString(&rec, r.stringField())
			case recordFieldInt:
				f.setInt(&rec, r.u32())
			case recordFieldChange:
				f.setChange(&rec, r.change())
			case recordFieldDecision:
				f.setDecision(&rec, r.decisionRecord())
			}
		}
		records = append(records, rec)
	}
	if r.err != nil {
		return decodedArchiveFrame{}, r.err
	}
	if r.pos != len(payload) {
		return decodedArchiveFrame{}, fmt.Errorf("%w: %d unconsumed archive bytes", ErrInvalidArchive, len(payload)-r.pos)
	}
	return decodedArchiveFrame{
		records:     records,
		org:         embeddedOrg,
		endSeq:      embeddedEndSeq,
		fingerprint: embeddedFingerprint,
	}, nil
}

// validateDecodedFrame applies the content checks to a parsed frame and
// returns the material as VerifiedAuditMaterial after the single complete
// VerifyAudit chain pass. The embedded checkpoint is informational; still,
// contradicting the retained checkpoint means the payload was altered, and
// the authoritative check always uses the caller's independently retained
// checkpoint.
func validateDecodedFrame(frame decodedArchiveFrame, org string, cp Checkpoint) (VerifiedAuditMaterial, error) {
	// Content checks reuse the exact audit-range validation the live export
	// and offline review paths use, so an archive can never smuggle in a
	// shape those entry points would reject.
	if frame.org != org {
		return VerifiedAuditMaterial{}, fmt.Errorf("%w: archive organization %q does not match %q", ErrInvalidRange, frame.org, org)
	}
	if frame.endSeq != cp.EndSeq || frame.fingerprint != cp.Fingerprint {
		return VerifiedAuditMaterial{}, fmt.Errorf("%w: embedded checkpoint does not match the retained checkpoint", ErrInvalidRange)
	}
	return verifyAuditMaterial(org, frame.records, cp)
}

// DecodeVerifiedAuditArchive reads one archive produced by
// EncodeAuditArchive, validates it once, and returns the material ready
// for RecheckVerifiedDecisionOffline. It is the single-validation half of
// the offline review flow: the returned VerifiedAuditMaterial carries the
// already-checked chain, so the following review performs no second chain
// pass. org is the organization the caller expects, and cp is the
// checkpoint the caller independently retained; the checkpoint embedded in
// the file is never treated as evidence, so even an archive carrying a
// plausible checkpoint only validates against the one supplied here.
//
// A missing organization is ErrMissingOrganization. Unrecognized framing,
// truncation, a trailing second archive or any other extra byte, a bad
// checksum, and undecodable content are ErrInvalidArchive. Records that
// decode but are missing, out of order, foreign to the organization,
// modified (including a record after the one the caller intends to review)
// or mismatched with the supplied checkpoint fail the whole read with
// ErrInvalidRange. Failure returns no material. A successful read only
// proves the material matches the checkpoint: an original decision that
// disagrees with a recomputed one is reported later by offline review, not
// treated as archive damage. The material is detached from archive
// (mutating one never reaches the other), and the call is read-only.
func DecodeVerifiedAuditArchive(archive []byte, org string, cp Checkpoint) (VerifiedAuditMaterial, error) {
	if org == "" {
		return VerifiedAuditMaterial{}, ErrMissingOrganization
	}
	frame, err := decodeAuditArchiveFrame(archive)
	if err != nil {
		return VerifiedAuditMaterial{}, err
	}
	return validateDecodedFrame(frame, org, cp)
}

// DecodeAuditArchive reads one archive produced by EncodeAuditArchive and
// returns records that can be handed directly to RecheckDecisionOffline.
// org is the organization the caller expects, and cp is the checkpoint the
// caller independently retained; the checkpoint embedded in the file is
// never treated as evidence, so even an archive carrying a plausible
// checkpoint only validates against the one supplied here.
//
// This is a standalone entry point: it performs the complete archive and
// chain validation itself and never assumes another entry point ran first.
// (The `darksafe review` command instead uses DecodeVerifiedAuditArchive
// followed by RecheckVerifiedDecisionOffline, so one invocation validates
// the chain exactly once rather than once here and again in the review.)
//
// A missing organization is ErrMissingOrganization. Unrecognized framing,
// truncation, a trailing second archive or any other extra byte, a bad
// checksum, and undecodable content are ErrInvalidArchive. Records that
// decode but are missing, out of order, foreign to the organization,
// modified (including a record after the one the caller intends to review)
// or mismatched with the supplied checkpoint fail the whole read with
// ErrInvalidRange. Failure returns no records. A successful read only
// proves the material matches the checkpoint: an original decision that
// disagrees with a recomputed one is reported later by offline review, not
// treated as archive damage. The result is detached from archive (mutating
// one never reaches the other), and the call is read-only.
func DecodeAuditArchive(archive []byte, org string, cp Checkpoint) ([]AuditRecord, error) {
	m, err := DecodeVerifiedAuditArchive(archive, org, cp)
	if err != nil {
		return nil, err
	}
	return m.records, nil
}

// The JSON renderer for `darksafe review --json`. It serializes the very
// same OfflineDecisionReview the text report prints: the same archive
// validation and historical recheck feed both, so choosing JSON can never
// change the consistency verdict.
//
// String representation rule (part of the command contract):
//
//   - A string that is valid UTF-8 is emitted as an ordinary JSON string.
//     encoding/json performs the mandatory escaping only: quotation marks,
//     backslashes and control characters become escape sequences, while
//     ordinary Chinese and a genuine U+FFFD stay readable UTF-8.
//   - A string that is NOT valid UTF-8 is emitted as the object
//     {"base64": "<RFC 4648 standard base64>"} carrying the standard
//     base64 encoding of the string's exact bytes. The two shapes are
//     disjoint (a JSON string can never be an object), so a receiver can
//     recover every string's original bytes, and a lone 0xFF, a lone 0xFE
//     and a real U+FFFD stay distinguishable instead of collapsing onto
//     one replacement character.
package main

import (
	"encoding/base64"
	"encoding/json"
	"unicode/utf8"

	"github.com/asdhoaiqqq/darksafe-access/darksafe"
)

// jsonReview is the top-level --json object. Field order mirrors the text
// report: target sequence first, then the original decision, the
// recomputed decision, and the consistency verdict. The target sequence is
// a separate field from either decision's policy_version.
type jsonReview struct {
	TargetSequence int          `json:"target_sequence"`
	Original       jsonDecision `json:"original"`
	Recomputed     jsonDecision `json:"recomputed"`
	Consistent     bool         `json:"consistent"`
}

// jsonDecision mirrors one text-report decision block.
type jsonDecision struct {
	Allowed         bool  `json:"allowed"`
	Reason          any   `json:"reason"`
	MatchedPolicies []any `json:"matched_policies"`
	PolicyVersion   int   `json:"policy_version"`
}

// renderReviewJSON builds the complete JSON object for one review. It is a
// pure function of the review result: runReview calls it only after every
// validation has succeeded and writes its output in one piece, so a failed
// review can never leave a partial object on stdout.
func renderReviewJSON(r darksafe.OfflineDecisionReview) ([]byte, error) {
	out := jsonReview{
		TargetSequence: r.Seq,
		Original:       toJSONDecision(r.Original),
		Recomputed:     toJSONDecision(r.Recomputed),
		Consistent:     r.Consistent,
	}
	// Indentation keeps the single object human-readable; it is still one
	// complete JSON object with no surrounding text.
	b, err := json.MarshalIndent(out, "", "  ")
	if err != nil {
		return nil, err
	}
	return append(b, '\n'), nil
}

// toJSONDecision converts one decision. Matched policy identifiers keep
// their stored order, and a nil matched list renders the same [] as an
// empty list: the list is always allocated non-nil, matching the review's
// own nil-equals-empty consistency rule.
func toJSONDecision(d darksafe.Decision) jsonDecision {
	matched := make([]any, 0, len(d.Matched))
	for _, id := range d.Matched {
		matched = append(matched, jsonStringValue(id))
	}
	return jsonDecision{
		Allowed:         d.Allowed,
		Reason:          jsonStringValue(d.Reason),
		MatchedPolicies: matched,
		PolicyVersion:   d.Version,
	}
}

// jsonStringValue maps one raw Go string to its JSON value: the string
// itself when it is valid UTF-8, otherwise a {"base64": ...} object over
// its exact bytes.
func jsonStringValue(s string) any {
	if utf8.ValidString(s) {
		return s
	}
	return map[string]string{"base64": base64.StdEncoding.EncodeToString([]byte(s))}
}

