	}
	if !seenEndSeq {
		return darksafe.Checkpoint{}, fmt.Errorf("checkpoint %q: missing field end_seq", path)
	}
	if !seenFingerprint {
		return darksafe.Checkpoint{}, fmt.Errorf("checkpoint %q: missing field fingerprint", path)
	}
	return cp, nil
