// Checkpoint-file reading for `darksafe review --checkpoint FILE`. The
// separately retained checkpoint is the same small plain-text document the
// offline_review example writes: one key=value item per line, three keys
// (org, end_seq, fingerprint) each exactly once, in any order, with one
// optional trailing newline.
//
// Byte fidelity matters most: the org line uses Go-style double quoting
// (the same spelling fmt.Sprintf("org=%q", ...) emits), and reading it
// back must restore the organization's ORIGINAL bytes — Chinese, leading
// and trailing spaces, escaped control characters and non-UTF-8 bytes
// (0xff and 0xfe written as \xff/\xfe, never folded onto U+FFFD).
//
// Every shape deviation is an invocation error the review command reports
// with exit code 2: the file cannot be read, a field is missing or
// repeated, an unknown key or non-empty stray line appears, the quoted
// organization is empty or mis-escaped, the end sequence is not a
// non-negative decimal integer the process's int type can represent, or
// the fingerprint is not 64 lowercase-or-uppercase hexadecimal characters.
package main

import (
	"fmt"
	"os"
	"strconv"
	"unicode/utf8"
)

// readCheckpointFile reads and strictly parses one independently saved
// checkpoint document. It returns the file error verbatim so the command
// can name the offending file, and field errors that name the specific
// item and what was wrong with it.
func readCheckpointFile(path string) (cp darksafe.Checkpoint, err error) {
	data, err := os.ReadFile(path)
	if err != nil {
		return darksafe.Checkpoint{}, fmt.Errorf("cannot read checkpoint %q: %v", path, err)
	}
	return parseCheckpointDocument(path, data)
}

// parseCheckpointDocument validates the document shape and decodes the
// three items. Splitting on '\n' means no item value can ever smuggle a
// newline across line boundaries; the single trailing newline the format
// allows is consumed by trimming exactly one from the tail.
func parseCheckpointDocument(path string, data []byte) (darksafe.Checkpoint, error) {
	// A completely empty file (or one containing only a newline) carries
	// no items at all and fails below as missing every field.
	if len(data) > 0 && data[len(data)-1] == '\n' {
		data = data[:len(data)-1]
	}

	var cp darksafe.Checkpoint
	var seen [3]bool // org, end_seq, fingerprint
	lineNo := 0
	for rest := data; ; {
		lineNo++
		var line []byte
		if idx := indexByte(rest, '\n'); idx >= 0 {
			line = rest[:idx]
			rest = rest[idx+1:]
		} else {
			line = rest
			rest = nil
		}

		key, value, ok := splitKeyValue(line, path, lineNo)
		if !ok {
			return darksafe.Checkpoint{}, err
		}

		switch key {
		case "org":
			if seen[0] {
				return darksafe.Checkpoint{}, fmt.Errorf(
					"checkpoint %q line %d: duplicate field %q", path, lineNo, key)
			}
			seen[0] = true
			// A raw invalid byte or raw control character embedded in the
			// quoted literal is rejected so the document is pure
			// ASCII-structured: org bytes reach the parser only through
			// Go escapes, which Unquote restores exactly.
			if !quotedLiteralIsClean(value) {
				return darksafe.Checkpoint{}, fmt.Errorf(
					"checkpoint %q line %d: org has a raw control or non-UTF-8 byte; escape it Go-style (e.g. \\xff)",
					path, lineNo)
			}
			org, uerr := strconv.Unquote(value)
			if uerr != nil || len(value) < 2 || value[0] != '"' || value[len(value)-1] != '"' {
				return darksafe.Checkpoint{}, fmt.Errorf(
					"checkpoint %q line %d: org must be a Go-style double-quoted string, got %q",
					path, lineNo, value)
			}
			if org == "" {
				return darksafe.Checkpoint{}, fmt.Errorf(
					"checkpoint %q line %d: org must not be empty", path, lineNo)
			}
			cp.Org = org
		case "end_seq":
			if seen[1] {
				return unnamedDuplicateError(path, lineNo, key)
			}
			seen[1] = true
			if !isDecimalInt(value) || len(value) == 0 {
				return darksafe.Checkpoint{}, fmt.Errorf(
					"checkpoint %q line 2: invalid end_seq %q: must be a non-negative decimal integer",
					path, value)
			}
			n, _ := strconv.Atoi(string(value))
			cp.EndSeq = n
		case "fingerprint":
			if seen[2] {
				return unnamedDuplicateError(path, lineNo, key)
			}
			seen[2] = true
			if !isHexFingerprint(value)HexFingerprint(value) {
				return darksafe.Checkpoint{}, fmt.Errorf(
					"checkpoint %q line %d: invalid fingerprint %q: must be 64 hexadecimal characters",
					path, lineNo, value)
			}
			cp.Fingerprint = string(value)
		default:
			return darksafe.Checkpoint{}, fmt.Errorf(
				"checkpoint %q line %d: unknown field %q", path, lineNo, key)
		}

		if rest == nil {
			break
		}
	}

	if !seen[0] {
		return darksafe.Checkpoint{}, fmt.Errorf("checkpoint %q: missing field org", path)
	}
	if !seen[1] {
		return darksafe.Checkpoint{}, fmt.Errorf("checkpoint %q: missing field end_seq", path)
	}
	if !seen[2] {
		return darksafe.Checkpoint{}, fmt.Errorf("
", path) // placeholder, replaced below
	}
	return cp, nil
}

